<script setup lang="ts">
import { computed, ref } from 'vue'
import { SlidersHorizontal, Link2, Zap, MousePointer2 } from 'lucide-vue-next'
import ValueEditor from './ValueEditor.vue'
import FButton from './fluent/FButton.vue'
import QuickActionEditor from './QuickActionEditor.vue'
import type { Editor } from '../lib/editor'
import type { ValueRef } from '../lib/model'
const props = defineProps<{ editor: Editor }>()
const tab = ref('properties'), bindingProperty = ref('value')
const widget = computed(() => props.editor.selectedWidgets.value[0])
function field(key: string, value: any, property = false) { if (!widget.value) return; props.editor.mutate(() => { if (property) widget.value!.props[key] = value; else (widget.value as any)[key] = value }) }
function number(event: Event) { return Number((event.target as HTMLInputElement).value) }
function binding(key: string, value: ValueRef) { props.editor.mutate(() => widget.value!.bindings[key] = value) }
function bindEvent(event: Event) { const [flowId, entryNodeId] = (event.target as HTMLSelectElement).value.split(':'); props.editor.mutate(() => { const name = widget.value!.kind === 'button' ? 'click' : 'change'; if (!flowId) delete widget.value!.events[name]; else widget.value!.events[name] = { kind: 'flow', flowId, entryNodeId } }) }
</script>

<template>
  <aside class="inspector">
    <div class="panel-title">{{ widget ? '控件设置' : '页面设置' }}<span v-if="editor.selectedWidgets.value.length > 1" class="tiny-badge">{{ editor.selectedWidgets.value.length }} 个选中</span></div>
    <template v-if="widget"><div class="inspector-object"><span class="object-symbol"><MousePointer2 :size="18" /></span><div><strong>{{ widget.name }}</strong><small>{{ widget.kind }} · {{ widget.id.slice(-8) }}</small></div></div><div class="inspector-tabs"><button :class="{ active: tab === 'properties' }" @click="tab = 'properties'"><SlidersHorizontal :size="14" />属性</button><button :class="{ active: tab === 'bindings' }" @click="tab = 'bindings'"><Link2 :size="14" />绑定</button><button :class="{ active: tab === 'events' }" @click="tab = 'events'"><Zap :size="14" />事件</button></div>
      <div v-if="tab === 'properties'" class="inspector-scroll"><section class="property-section"><h4>基本信息</h4><label>控件名称<input :value="widget.name" @change="field('name', ($event.target as HTMLInputElement).value)" /></label><label>显示文本<input :value="widget.props.text" @change="field('text', ($event.target as HTMLInputElement).value, true)" /></label></section><section class="property-section"><h4>位置与尺寸</h4><div class="property-grid"><label>X<input type="number" :value="widget.x" @change="field('x', number($event))" /></label><label>Y<input type="number" :value="widget.y" @change="field('y', number($event))" /></label><label>宽度<input type="number" min="24" :value="widget.width" @change="field('width', Math.max(24, number($event)))" /></label><label>高度<input type="number" min="24" :value="widget.height" @change="field('height', Math.max(24, number($event)))" /></label></div><label>层级<input type="number" :value="widget.zIndex" @change="field('zIndex', number($event))" /></label></section><section class="property-section"><h4>外观</h4><div class="property-grid"><label>字号<input type="number" min="8" :value="widget.props.fontSize" @change="field('fontSize', Math.max(8, number($event)), true)" /></label><label>文字颜色<input type="color" :value="widget.props.color" @change="field('color', ($event.target as HTMLInputElement).value, true)" /></label></div><label>背景颜色<input type="color" :value="widget.props.background" @change="field('background', ($event.target as HTMLInputElement).value, true)" /></label><label v-if="['number', 'chart'].includes(widget.kind)">单位<input :value="widget.props.unit" @change="field('unit', ($event.target as HTMLInputElement).value, true)" /></label><label v-if="widget.kind === 'number'">小数位数<input type="number" min="0" max="8" :value="widget.props.precision" @change="field('precision', Math.max(0, Math.min(8, number($event))), true)" /></label><label v-if="['input','number','select'].includes(widget.kind)">初始值<input :value="widget.props.value" @change="field('value', ($event.target as HTMLInputElement).value, true)" /></label><label v-if="widget.kind === 'select'">选项（每行一个）<textarea :value="widget.props.options?.join('\n')" rows="4" @change="field('options', ($event.target as HTMLTextAreaElement).value.split('\n').filter(Boolean), true)" /></label><label>背景图片<select :value="widget.props.backgroundAssetId ?? ''" @change="field('backgroundAssetId', ($event.target as HTMLSelectElement).value, true)"><option value="">无</option><option v-for="asset in editor.project.value.assets?.filter(asset => /\.(png|jpe?g|webp|svg)$/i.test(asset.path))" :key="asset.id" :value="asset.id">{{ asset.path.split('/').pop() }}</option></select></label><label>本地字体<select :value="widget.props.fontAssetId ?? ''" @change="field('fontAssetId', ($event.target as HTMLSelectElement).value, true)"><option value="">默认系统字体</option><option v-for="asset in editor.project.value.assets?.filter(asset => /\.(ttf|otf|woff2?)$/i.test(asset.path))" :key="asset.id" :value="asset.id">{{ asset.path.split('/').pop() }}</option></select></label><label class="checkbox-label"><input type="checkbox" :checked="widget.props.visible !== false" @change="field('visible', ($event.target as HTMLInputElement).checked, true)" />可见</label><label class="checkbox-label"><input type="checkbox" :checked="widget.props.enabled !== false" @change="field('enabled', ($event.target as HTMLInputElement).checked, true)" />启用</label></section></div>
      <div v-else-if="tab === 'bindings'" class="inspector-scroll"><section class="property-section"><p class="muted-copy">将显示值或状态连接到项目变量与设备数据。</p><div v-for="(value, key) in widget.bindings" :key="key" class="binding-card"><div class="inline-between"><strong>{{ key }}</strong><button class="text-button" @click="editor.mutate(() => delete widget!.bindings[key])">移除</button></div><ValueEditor :model-value="value" :project="editor.project.value" @update:model-value="binding(key, $event)" /></div><label>绑定属性<select v-model="bindingProperty"><option value="value">显示值</option><option value="text">显示文本</option><option value="enabled">启用状态</option><option value="visible">可见状态</option></select></label><FButton class="full-width" @click="binding(bindingProperty, { source: 'variable', key: editor.project.value.variables[0]?.id ?? '' })"><Link2 :size="14" />添加数据绑定</FButton></section></div>
      <div v-else class="inspector-scroll"><QuickActionEditor :editor="editor" :widget="widget" /><section class="property-section"><h4>{{ widget.kind === 'button' ? '点击时' : '值改变时' }}</h4><label>业务流程<select :value="Object.values(widget.events)[0]?.kind === 'flow' ? `${Object.values(widget.events)[0]?.flowId}:${Object.values(widget.events)[0]?.entryNodeId}` : ''" @change="bindEvent"><option value="">无操作</option><template v-for="flow in editor.project.value.flows" :key="flow.id"><option v-for="node in flow.nodes.filter(n => n.kind === 'trigger.ui')" :key="node.id" :value="`${flow.id}:${node.id}`">{{ flow.name }} / {{ node.label }}</option></template></select></label><p class="muted-copy">在「逻辑流程」中添加界面事件节点，再选择需要触发的入口。</p><h4>运行管理</h4><label>宿主控制<select :value="Object.values(widget.events)[0]?.kind !== 'flow' ? `${Object.values(widget.events)[0]?.kind}:${Object.values(widget.events)[0]?.flowId}` : ''" @change="editor.mutate(() => { const [kind, flowId] = ($event.target as HTMLSelectElement).value.split(':'); if (flowId) widget!.events[widget!.kind === 'button' ? 'click' : 'change'] = { kind: kind as 'startFlow' | 'stopFlow', flowId } })"><option value="">无管理操作</option><template v-for="flow in editor.project.value.flows" :key="flow.id"><option :value="`startFlow:${flow.id}`">恢复：{{ flow.name }}</option><option :value="`stopFlow:${flow.id}`">停止：{{ flow.name }}</option></template></select></label></section></div>
    </template>
    <div v-else class="inspector-scroll"><section class="property-section"><label>页面名称<input :value="editor.page.value.name" @change="editor.mutate(() => editor.page.value.name = ($event.target as HTMLInputElement).value)" /></label><h4>项目画布</h4><div class="property-grid"><label>宽度<input type="number" min="100" :value="editor.project.value.width" @change="editor.mutate(p => p.width = Math.max(100, number($event)))" /></label><label>高度<input type="number" min="100" :value="editor.project.value.height" @change="editor.mutate(p => p.height = Math.max(100, number($event)))" /></label></div><p class="muted-copy">运行时等比缩放，居中显示。选择画布上的控件可编辑其属性和交互。</p></section><section class="property-section"><h4>快捷操作</h4><div class="shortcut"><span>撤销 / 重做</span><kbd>Ctrl Z / Y</kbd></div><div class="shortcut"><span>复制控件</span><kbd>Ctrl D</kbd></div><div class="shortcut"><span>删除控件</span><kbd>Delete</kbd></div><div class="shortcut"><span>多选</span><kbd>Shift 点击</kbd></div><div class="shortcut"><span>保存项目</span><kbd>Ctrl S</kbd></div></section></div>
  </aside>
</template>
